entries.raw_text:
if = {
					limit = {
						scope:enemy_knight = {
							tgp_cranial_trophies_collection_trigger = yes
						}
					}
					tgp_cranial_trophies_beheading_effect = {
						KILLER = scope:enemy_knight
						DEAD = scope:knight
					}
				}

if = {
			limit = {
				exists = liege
				is_knight_of = liege
				OR = {
					is_acclaimed = yes
					is_close_family_of = liege
					is_consort_of = liege
					is_powerful_vassal_of = liege
					has_relation_blood_brother = liege
				}
				liege = {
					has_none_of_variables = {
						name = beheaded_warrior
						name = beheaded_warrior_cooldown
					}
					OR = {
						faith.religion = faith:tengri_pagan.religion
						AND = {
							culture = {
								OR = {
									has_cultural_pillar = heritage_mongolic
									has_cultural_pillar = heritage_turkic
								}
							}
							has_trait = nomadic_philosophy
						}
					}
				}
				scope:combat_side = {
					any_side_participant = {
						this = root.liege
					}
				}
			}
			liege = {
				set_variable = {
					name = beheaded_warrior
					value = root
				}
				set_variable = {
					name = beheaded_warrior_foe
					value = scope:combat_side.enemy_side.side_primary_participant
				}
				set_variable = {
					name = beheaded_warrior_location
					value = scope:combat_side.combat.location
				}
				if = {
					limit = {
						root = { is_powerful_vassal_of = liege }
					}
					set_variable = {
						name = beheaded_warrior_powerful_vassal
						value = root
					}
				}
				else_if = {
					limit = {
						root = { is_councillor_of = liege }
					}
					set_variable = {
						name = beheaded_warrior_councillor
						value = root
					}
				}
				if = {
					limit = {
						root = {
							is_acclaimed = yes
						}
					}
					set_variable = {
						name = beheaded_warrior_accolade
						value = root.accolade
					}
				}
			}
		}

faith = {
								faith_hostility_level = {
									target = root.faith
									value >= faith_evil_level
								}
							}

if = {
		limit = {
			has_personal_tenet_flag = tenet_exaltation_of_pain_wounded_spiritual_fulfillment
			NOT = {
				has_trait_rank = {
					trait = wounded
					rank = 3
				}
			}
		}
		save_temporary_scope_value_as = {
			name = exaltation_of_pain_wounded_spiritual_fulfillment
			value = yes
		}
	}

if = {
		limit = {
			scope:exaltation_of_pain_wounded_spiritual_fulfillment = yes
			has_trait_rank = {
				trait = wounded
				rank = 1
			}
		}
		if = {
			limit = { is_ai = no }
			send_interface_toast = {
				type = event_generic_good
				title = exaltation_of_pain_wounded_spiritual_fulfillment_toast
				left_icon = this
				change_spiritual_fulfillment = minor_spiritual_fulfillment_value
			}
		}
		else = {
			change_spiritual_fulfillment = minor_spiritual_fulfillment_value
		}
	}

else_if = {
		limit = {
			scope:exaltation_of_pain_wounded_spiritual_fulfillment = yes
			has_trait_rank = {
				trait = wounded
				rank = 2
			}
		}
		if = {
			limit = { is_ai = no }
			send_interface_toast = {
				type = event_generic_good
				title = exaltation_of_pain_wounded_spiritual_fulfillment_toast
				left_icon = this
				change_spiritual_fulfillment = medium_spiritual_fulfillment_value
			}
		}
		else = {
			change_spiritual_fulfillment = medium_spiritual_fulfillment_value
		}
	}

else_if = {
		limit = {
			scope:exaltation_of_pain_wounded_spiritual_fulfillment = yes
			has_trait_rank = {
				trait = wounded
				rank = 3
			}
		}
		if = {
			limit = { is_ai = no }
			send_interface_toast = {
				type = event_generic_good
				title = exaltation_of_pain_wounded_spiritual_fulfillment_toast
				left_icon = this
				change_spiritual_fulfillment = major_spiritual_fulfillment_value
			}
		}
		else = {
			change_spiritual_fulfillment = major_spiritual_fulfillment_value
		}
	}

if = {
		limit = { has_personal_tenet_flag = tenet_mortification_suffering_sanctifies }
		if = {
			limit = { is_ai = no }
			send_interface_toast = {
				type = event_generic_good
				title = pam_mortification_suffering_sanctifies_toast
				left_icon = this
				add_piety = minor_piety_value
				add_stress = minor_stress_loss
			}
		}
		else = {
			add_piety = minor_piety_value
			add_stress = minor_stress_loss
		}
	}

